/// <summary>
/// Response data contract class for <c>METUpdateSalesInvoiceIntegrationStatusService</c> class.
/// </summary>
[DataContractAttribute]
class METUpdateSalesInvoiceIntegrationStatusResponseContract
{
    private boolean     success;
    private str         message;
    private InvoiceId   invoiceId;
    private CustAccount custAccount;

}

Method.Source:
    /// <summary>
    /// Method used to specify if the error message
    /// </summary>
    /// <param name = "_message">update result as a message</param>
    /// <returns>update result/error message if any</returns>
    [
        DataMemberAttribute('@MET:Message'),
        SysOperationLabelAttribute(literalstr("@MET:Message"))
    ]
    public str parmMessage(str _message = message)
    {
        if (!prmIsDefault(_message))
        {
            message = _message;
        }

        return message;
    }

    /// <summary>
    /// Method to specify if the update was successful
    /// </summary>
    /// <param name = "_success">update result</param>
    /// <returns>True is success/false if update fails</returns>
    [
        DataMemberAttribute('@MET:Result'),
        SysOperationLabelAttribute(literalstr("@MET:Result"))
    ]
    public Boolean parmSuccess(Boolean _success = success)
    {
        if (!prmIsDefault(_success))
        {
            success = _success;
        }

        return success;
    }

/// <summary>
/// Method to specify the invoice number
/// </summary>
/// <param name = "_invoiceId">sales invoice number</param>
/// <returns>return the sales invoice number</returns>
[
    DataMemberAttribute('InvoiceId'),
    SysOperationLabelAttribute(literalstr("@MET:InvoiceId"))
]
public InvoiceId parmInvoiceId(InvoiceId _invoiceId = invoiceId)
{
    if (!prmIsDefault(_invoiceId))
    {
        invoiceId = _invoiceId;
    }
    return invoiceId;
}

/// <summary>
/// Method to specify the customer account number
/// </summary>
/// <param name = "_custAccount">customer account number</param>
/// <returns>returns the customer account number</returns>
[
    DataMemberAttribute('CustomerAccountNumber'),
    SysOperationLabelAttribute(literalstr("@MET:CustomerAccountNumber"))
]
public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    if (!prmIsDefault(_custAccount))
    {
        custAccount = _custAccount;
    }
    return custAccount;
}
